sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float sweep;
uniform float alpha;
uniform float bias;
uniform float mode;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float2 c = center * size;
    float span = radians(sweep);
    if (span <= 0.0) return src;
    float2 d = coord - c;
    float4 hi = float4(0.0);
    float4 sum = float4(0.0);
    float3 lo = float3(1.0);
    for (int i = 0; i < 48; i++) {
        float a = span * 0.5 * mix(bias - 1.0, bias + 1.0, float(i) / 47.0);
        float cs = cos(a);
        float sn = sin(a);
        float4 v = float4(image.eval(c + float2(cs * d.x - sn * d.y, sn * d.x + cs * d.y)));
        hi = max(hi, v);
        sum += v;
        if (v.a > 0.002) lo = min(lo, v.rgb / v.a);
    }
    float4 acc = mode < 0.5 ? hi : mode < 1.5 ? sum / 48.0 : float4(lo * hi.a, hi.a);
    return half4(mix(float4(src), acc, clamp(alpha, 0.0, 1.0)));
}
